package com.bowerzlabs.kraftpulse.shared.model;

import java.time.Instant;
import java.util.List;

/**
 * Represents an N+1 query cascade warning generated by KraftPulse's in-flight query analyzer.
 * Fired when identical or structurally equivalent queries execute repeatedly within a single trace boundary.
 *
 * @param id                 Unique warning event ID generated using SHA-256 of (traceId + normalizedQuery + repositoryMethod).
 * @param traceId            Global W3C trace ID where the N+1 cascade occurred.
 * @param parentSpanId       Span ID of the parent HTTP request or job that triggered the query cascade.
 * @param applicationName    Name of the application exhibiting the N+1 pattern.
 * @param databaseType       Database engine type (e.g., "POSTGRESQL", "MONGODB").
 * @param repositoryClass    Spring Data repository class or DAO executing the cascaded calls.
 * @param repositoryMethod   Spring Data repository method or DAO method executing the cascaded calls.
 * @param normalizedQuery    Normalized query template being repeatedly invoked (e.g., "SELECT * FROM order_items WHERE order_id = ?").
 * @param occurrenceCount    Total number of times this specific query structure executed during the single trace context.
 * @param totalDurationMs    Cumulative execution time spent across all repeated query iterations in milliseconds.
 * @param sampleSpanIds      List of up to 5 sample span IDs for individual queries in the cascade (for timeline correlation).
 * @param detectedAt         Timestamp when the N+1 threshold was crossed.
 */
public record NPlusOneWarningEvent(
        String id,
        String traceId,
        String parentSpanId,
        String applicationName,
        String databaseType,
        String repositoryClass,
        String repositoryMethod,
        String normalizedQuery,
        int occurrenceCount,
        long totalDurationMs,
        List<String> sampleSpanIds,
        Instant detectedAt
) implements KraftPulseEvent {

    public NPlusOneWarningEvent {
        sampleSpanIds = sampleSpanIds == null ? List.of() : List.copyOf(sampleSpanIds);
    }

    @Override
    public EventMetadata metadata() {
        return new EventMetadata(
                id,
                detectedAt,
                applicationName,
                traceId,
                parentSpanId != null ? parentSpanId : ""
        );
    }
}